// These are necessary definitions that let you graphics card know how to render the shader
#ifdef GL_ES
precision highp float;
#endif

// Vertex attributes
attribute vec3 aPosition;
attribute vec2 aTexCoord;

// Pass-through to the fragment shader
varying vec2 vTexCoord;

void main() {
    // Pass texture coordinates to the fragment shader
    vTexCoord = aTexCoord;

    // Transform the position into normalized device coordinates (NDC)
    vec4 positionVec4 = vec4(aPosition, 1.0);

    // Scale and shift to NDC (Normalize Device Coordinate) range [-1, 1]
    positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

    // Set the final position of the vertex
    gl_Position = positionVec4;
}


// === Tab: fragment.glsl ===
/*
 * Orignal shader by byt3_m3chanic
 * https://www.shadertoy.com/view/wcGSRh
 * It is a little slow for large views. :( 
 * I will try to optimize it later.
 */

// These are necessary definitions that let you graphics card know how to render the shader
#ifdef GL_ES
precision highp float;
#endif

// These are our passed in information from the sketch.js
uniform vec2 iResolution;
uniform float iTime;

#define R iResolution
#define T (iTime+15.)
#define r2(a) mat2(cos(a+vec4(0,11,33,0)))
#define h21(p) fract(sin(dot(p,vec2(27.69,32.58)))*4378.53)

varying vec2 vTexCoord;

void main() {
    // Map vTexCoord to normalized device coordinates (NDC) [-1, 1]
    vec2 uv = vTexCoord * 2.0 - 1.0;

    // Define a scale factor
    const float scale = 1.0;

    // Adjust for aspect ratio and scale the coordinates
    uv.x *= scale * iResolution.x / iResolution.y;
    uv.y *= scale;

    // Declare necessary variables
    vec3 position, tileID, baseColor;
    float stepCount = 0.0;
    float totalDistance = 0.0;
    float time = T * 0.5;
    float hashVal, distEstimate;

    // Create slow rotation matrix for the whole scene
    mat2 slowRotation = r2(time * 0.08);
    mat2 dynamicRotation;

		const float maxSteps = 800.0;

    // Raymarching loop (up to 800 steps)
    for (float i = 0.0; i < maxSteps; i++) {
			  //stepCount = i + 1.0;
        // Project current distance along ray direction
        position = totalDistance * vec3(uv, 1.0);

        // Rotate around xz plane
        position.xz *= slowRotation;

        // Shift scene to the right for better centering
        position.x += 4.5;

        // Determine which 8x8 tile we're in (on xz-plane)
        tileID = floor((position + 4.0) / 8.0);

        // Hash tile ID to get variation
        hashVal = h21(tileID.xz) * 1.5;

        // Animate objects falling downward based on hash/time
        position.y += -T * hashVal * 3.0;

        // Recalculate tile ID after animation shift
        tileID = floor((position + 4.0) / 8.0);

        // Wrap position into local tile space [-4, 4]
        position = mod(position + 4.0, 8.0) - 4.0;

        // Hash the full 3D tile ID for more variation
        hashVal = h21(tileID.xy + tileID.z);

        // Create time-based rotation matrix
        dynamicRotation = r2(T * hashVal);

        // Apply rotation in zy and then xy planes
        position.zy *= dynamicRotation;
        position.xy *= dynamicRotation;

        // Add a horizontal wobble effect
        position.x += 1.5 * sin(hashVal * 3.0 + time);

        // Distance estimate to object (currently a sphere)
				distEstimate = length(position) - 1.25;

				//distEstimate = length(vec2(length(position.xz) - 1.25, position.y)) - 0.25; // Uncomment to see Torii

				//distEstimate = hashVal > 0.5 
        //    ? length(position) - 1.25   // If hashVal > 0.5 → SDF for sphere of radius 1.25
        //    : length(vec2(length(position.xz) - 1.25, position.y)) - 0.25;

        // Update total distance traveled along the ray
        // Use max to prevent tiny steps (avoid infinite loops)
        totalDistance += abs(max(abs(distEstimate), 1e-4) * 0.09);
    }

     // New blue-green palette
    baseColor = mix(vec3(0.2, 0.1, 0.2),   
                    vec3(0.1, 0.8, 0.5),    
                    clamp(uv.y + 0.5, 0.0, 1.0));

    // Output the final color with full opacity
    gl_FragColor = vec4(mix(baseColor, vec3(0.5), totalDistance * 0.02), 1.0);
}

